            background-size: cover;
            background-position: center;
        }

        .today-content {
            flex: 1;
            padding: 30px;
            display: flex;
            flex-direction: column;
            justify-content: center;
        }

        .tag {
            font-size: 12px;
            font-weight: 700;
            text-transform: uppercase;
            color: var(--text-secondary);
            margin-bottom: 10px;
        }

        .today-title {
            font-size: 24px;
            font-weight: 700;
            margin-bottom: 10px;
            line-height: 1.2;
        }

        /* 列表项 (App Row) */
        .app-row {
            display: flex;
            align-items: center;
            padding: 15px 0;
            border-bottom: 1px solid var(--separator);
        }

        .app-row:last-child {
            border-bottom: none;
        }

        .app-icon {
            width: 60px;
            height: 60px;
            border-radius: 14px;
            object-fit: cover;
            margin-right: 15px;
            box-shadow: 0 2px 8px rgba(0,0,0,0.1);
        }

        .app-info {
            flex: 1;
        }

        .app-name {
            font-size: 17px;
            font-weight: 600;
            color: var(--text-primary);
        }

        .app-sub {
            font-size: 13px;
            color: var(--text-secondary);
            margin-top: 2px;
        }

        .get-btn {
            background-color: #f2f2f7;
            color: var(--text-primary);
            border: none;
            padding: 8px 16px;
            border-radius: 20px;
            font-size: 13px;
            font-weight: 700;
            cursor: pointer;
            transition: all 0.2s;
            min-width: 70px;
        }

        .get-btn:hover {
            background-color: #e5e5ea;
        }

        .get-btn:active {
            transform: scale(0.95);
        }

        /* 底部导航 (模拟) */
        .bottom-nav {
            position: fixed;
            bottom: 0;
            width: 100%;
            height: 60px;
            background: rgba(255,255,255,0.9);
            backdrop-filter: blur(10px);
            border-top: 1px solid var(--separator);
            display: flex;
            justify-content: space-around;
            align-items: center;
            z-index: 100;
        }

        .nav-icon {
            width: 24px;
            height: 24px;
            background-color: #ccc;
            border-radius: 50%;
        }

        .nav-icon.active {
            background-color: var(--accent-blue);
        }

        /* 响应式调整 */
        @media (max-width: 600px) {
            .today-card {
                flex-direction: column;
                height: auto;
            }
            .today-img {
                height: 200px;
                flex: none;
            }
            .today-content {
                padding: 20px;
            }
        }
    </style>
</head>
<body>

    <!-- 顶部导航 -->
    <header>
        <div class="nav-tabs">
            <div class="nav-item active" onclick="switchTab(this, 'today')">今日</div>
